window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9dd5d01a40b876de"]={"versions": [{"id": "FIG-9dd5d01a40b876de", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des Metamodells für AUTOSAR Timing Extensions (<code>AUTOSAR_TPS_TimingExtensions</code>). Es stellt die Kernstruktur der Timing-Erweiterungen mit der abstrakten Basisklasse <code>TimingExtension</code>, deren Aggregationen von Beschreibungen und Bedingungen sowie deren Spezialisierungen für unterschiedliche architektonische Abstraktionsebenen und Sichten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die zentrale Basisklasse ist <code>TimingExtension</code> (erbt von <code>PackageableElement</code> / <code>ARElement</code>). Sie aggregiert per Komposition mit Stereotyp <code>«atpVariation»</code> und Kardinalität <code>0..*</code>:</p>\n<ul class=\"fig-list\"><li><code>+timingDescription</code>: verweist auf <code>TimingDescription</code> (erbt von <code>MultilanguageReferrable</code> / <code>Identifiable</code>).\n</li><li><code>+timingRequirement</code>: verweist auf <code>TimingConstraint</code> (erbt von <code>MultilanguageReferrable</code> / <code>Traceable</code>).\n</li><li><code>+timingGuarantee</code>: verweist auf <code>TimingConstraint</code>.\n</li></ul>\n<p class=\"fig-p\"><code>Identifiable</code> definiert die Attribute <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>.</p>\n<p class=\"fig-p\">Von <code>TimingExtension</code> leiten sich spezialisierte Timing-Klassen ab:</p>\n<ul class=\"fig-list\"><li><code>VfbTiming</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>): referenziert per gerichteter Assoziation <code>+component 1</code> ein <code>SwComponentType</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>).\n</li><li><code>SwcTiming</code>: referenziert per gerichteter Assoziation <code>+component 0..1</code> ein <code>SwComponentType</code> (mit Tagged Value <code>Association Tags: atp.Status = obsolete</code>) sowie per Assoziation <code>+behavior 0..1</code> ein <code>SwcInternalBehavior</code> (erbt von <code>InternalBehavior</code>).\n</li><li><code>SystemTiming</code>: referenziert per gerichteter Assoziation <code>+system 1</code> ein <code>System</code> (erbt von <code>AtpStructureElement</code>).\n</li><li><code>BswModuleTiming</code>: referenziert per gerichteter Assoziation <code>+behavior 1</code> ein <code>BswInternalBehavior</code> (erbt von <code>InternalBehavior</code>).\n</li><li><code>EcuTiming</code>: referenziert per gerichteter Assoziation <code>+ecuConfiguration 1</code> eine <code>EcucValueCollection</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Sequenzabläufe oder Zustandsübergänge. Es definiert die statische Metamodellstruktur zur Erfassung von Timing-Garantien, -Anforderungen und -Beschreibungen entlang der AUTOSAR-Entwicklungsartefakte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>TimingExtension</code> bildet das Wurzelelement für paketierbare Timing-Modellelemente. Die Kompositionsbeziehungen zu Timing-Beschreibungen und -Bedingungen unterliegen der AUTOSAR-Variantenbildung (<code>«atpVariation»</code>, spätmöglichster Bindezeitpunkt <code>vh.latestBindingTime = postBuild</code>). Die Assoziation von <code>SwcTiming</code> direkt zu <code>SwComponentType</code> ist als obsolet markiert (<code>atp.Status = obsolete</code>), da die Zuordnung stattdessen über das Verhalten <code>SwcInternalBehavior</code> (<code>+behavior 0..1</code>) erfolgt. Timing-Bedingungen (<code>TimingConstraint</code>) sind rückverfolgbar (<code>Traceable</code>).</p>"}, {"id": "FIG-f1496cd250b353db", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des Metamodells für AUTOSAR Timing Extensions (<code>AUTOSAR_TPS_TimingExtensions</code>). Es stellt die Kernstruktur der Timing-Erweiterungen mit der abstrakten Basisklasse <code>TimingExtension</code>, deren Aggregationen von Beschreibungen und Bedingungen sowie deren Spezialisierungen für unterschiedliche architektonische Abstraktionsebenen und Sichten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die zentrale Basisklasse ist <code>TimingExtension</code> (erbt von <code>PackageableElement</code> / <code>ARElement</code>). Sie aggregiert per Komposition mit Stereotyp <code>«atpVariation,atpSplitable»</code> und Kardinalität <code>0..*</code>:</p>\n<ul class=\"fig-list\"><li><code>+timingDescription</code>: verweist auf <code>TimingDescription</code> (erbt von <code>MultilanguageReferrable</code> / <code>Identifiable</code>).\n</li><li><code>+timingRequirement</code>: verweist auf <code>TimingConstraint</code> (erbt von <code>MultilanguageReferrable</code> / <code>Traceable</code>).\n</li><li><code>+timingGuarantee</code>: verweist auf <code>TimingConstraint</code>.\n</li></ul>\n<p class=\"fig-p\"><code>Identifiable</code> definiert die Attribute <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>.</p>\n<p class=\"fig-p\">Von <code>TimingExtension</code> leiten sich spezialisierte Timing-Klassen ab:</p>\n<ul class=\"fig-list\"><li><code>VfbTiming</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>): referenziert per gerichteter Assoziation <code>+component 1</code> ein <code>SwComponentType</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>).\n</li><li><code>SwcTiming</code>: referenziert per gerichteter Assoziation <code>+behavior 0..1</code> ein <code>SwcInternalBehavior</code> (erbt von <code>InternalBehavior</code>).\n</li><li><code>SystemTiming</code>: referenziert per gerichteter Assoziation <code>+system 1</code> ein <code>System</code> (erbt von <code>AtpStructureElement</code>).\n</li><li><code>BswModuleTiming</code>: referenziert per gerichteter Assoziation <code>+behavior 1</code> ein <code>BswInternalBehavior</code> (erbt von <code>InternalBehavior</code>).\n</li><li><code>EcuTiming</code>: referenziert per gerichteter Assoziation <code>+ecuConfiguration 1</code> eine <code>EcucValueCollection</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Sequenzabläufe oder Zustandsübergänge. Es definiert die statische Metamodellstruktur zur Erfassung von Timing-Garantien, -Anforderungen und -Beschreibungen entlang der AUTOSAR-Entwicklungsartefakte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>TimingExtension</code> bildet das Wurzelelement für paketierbare Timing-Modellelemente. Die Kompositionsbeziehungen zu Timing-Beschreibungen und -Bedingungen sind aufteilbar und variabilitätsfähig (<code>«atpVariation,atpSplitable»</code>, mit Bindezeitpunkt <code>vh.latestBindingTime = postBuild</code>). <code>SwcTiming</code> referenziert das Verhalten <code>SwcInternalBehavior</code> (<code>+behavior 0..1</code>). Timing-Bedingungen (<code>TimingConstraint</code>) erben von <code>Traceable</code> und unterstützen modellübergreifende Nachverfolgbarkeit.</p>"}, {"id": "FIG-4eaecf515185f41a", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des Metamodells für AUTOSAR Timing Extensions (<code>AUTOSAR_TPS_TimingExtensions</code>). Es stellt die Kernstruktur der Timing-Erweiterungen mit der abstrakten Basisklasse <code>TimingExtension</code>, deren Aggregationen von Beschreibungen und Bedingungen sowie deren Spezialisierungen für unterschiedliche architektonische Abstraktionsebenen und Sichten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die zentrale Basisklasse ist <code>TimingExtension</code> (erbt von <code>PackageableElement</code> / <code>ARElement</code>). Sie aggregiert per Komposition mit Stereotyp <code>«atpVariation,atpSplitable»</code> und Kardinalität <code>0..*</code>:</p>\n<ul class=\"fig-list\"><li><code>+timingDescription</code>: verweist auf <code>TimingDescription</code> (erbt von <code>MultilanguageReferrable</code> / <code>Identifiable</code>).\n</li><li><code>+timingRequirement</code>: verweist auf <code>TimingConstraint</code> (erbt von <code>MultilanguageReferrable</code> / <code>Traceable</code>).\n</li><li><code>+timingGuarantee</code>: verweist auf <code>TimingConstraint</code>.\n</li></ul>\n<p class=\"fig-p\"><code>Identifiable</code> definiert die Attribute <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>.</p>\n<p class=\"fig-p\">Von <code>TimingExtension</code> leiten sich spezialisierte Timing-Klassen ab:</p>\n<ul class=\"fig-list\"><li><code>VfbTiming</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>): referenziert per gerichteter Assoziation <code>+component 1</code> ein <code>SwComponentType</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>).\n</li><li><code>SwcTiming</code>: referenziert per gerichteter Assoziation <code>+behavior 0..1</code> ein <code>SwcInternalBehavior</code> (erbt von <code>InternalBehavior</code>).\n</li><li><code>SystemTiming</code>: referenziert per gerichteter Assoziation <code>+system 1</code> ein <code>System</code> (erbt von <code>AtpStructureElement</code>).\n</li><li><code>BswModuleTiming</code>: referenziert per gerichteter Assoziation <code>+behavior 1</code> ein <code>BswInternalBehavior</code> (erbt von <code>InternalBehavior</code>).\n</li><li><code>EcuTiming</code>: referenziert per gerichteter Assoziation <code>+ecuConfiguration 1</code> eine <code>EcucValueCollection</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Sequenzabläufe oder Zustandsübergänge. Es definiert die statische Metamodellstruktur zur Erfassung von Timing-Garantien, -Anforderungen und -Beschreibungen entlang der AUTOSAR-Entwicklungsartefakte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>TimingExtension</code> bildet das Wurzelelement für paketierbare Timing-Modellelemente. Die Kompositionsbeziehungen zu Timing-Beschreibungen und -Bedingungen sind aufteilbar und variabilitätsfähig (<code>«atpVariation,atpSplitable»</code>, mit Bindezeitpunkt <code>vh.latestBindingTime = postBuild</code>). <code>SwcTiming</code> referenziert das Verhalten <code>SwcInternalBehavior</code> (<code>+behavior 0..1</code>). Timing-Bedingungen (<code>TimingConstraint</code>) erben von <code>Traceable</code> und unterstützen modellübergreifende Nachverfolgbarkeit.</p>"}, {"id": "FIG-6bf3f37b0bd56be0", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des Metamodells für AUTOSAR Timing Extensions (<code>AUTOSAR_TPS_TimingExtensions</code>). Es stellt die Kernstruktur der Timing-Erweiterungen mit der abstrakten Basisklasse <code>TimingExtension</code>, deren Aggregationen von Beschreibungen und Bedingungen sowie deren Spezialisierungen für unterschiedliche architektonische Abstraktionsebenen und Sichten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Basisklasse ist <code>TimingExtension</code> (erbt von <code>PackageableElement</code> / <code>ARElement</code>). Sie aggregiert per Komposition mit <code>«atpVariation,atpSplitable»</code> und Kardinalität <code>0..*</code>:</p>\n<ul class=\"fig-list\"><li><code>+timingDescription</code>: verweist auf <code>TimingDescription</code> (erbt von <code>MultilanguageReferrable</code> / <code>Identifiable</code>).\n</li><li><code>+timingRequirement</code>: verweist auf <code>TimingConstraint</code> (erbt von <code>MultilanguageReferrable</code> / <code>Traceable</code>).\n</li><li><code>+timingGuarantee</code>: verweist auf <code>TimingConstraint</code>.\n</li></ul>\n<p class=\"fig-p\"><code>Identifiable</code> definiert die Attribute <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>.</p>\n<p class=\"fig-p\">Von <code>TimingExtension</code> leiten sich spezialisierte Timing-Klassen ab:</p>\n<ul class=\"fig-list\"><li><code>VfbTiming</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>): referenziert per gerichteter Assoziation <code>+component 1</code> ein <code>SwComponentType</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>).\n</li><li><code>SwcTiming</code>: referenziert per gerichteter Assoziation <code>+behavior 0..1</code> ein <code>SwcInternalBehavior</code> (erbt von <code>InternalBehavior</code>).\n</li><li><code>SystemTiming</code>: referenziert per gerichteter Assoziation <code>+system 1</code> ein <code>System</code> (erbt von <code>AtpStructureElement</code>).\n</li><li><code>EcuTiming</code>: referenziert per gerichteter Assoziation <code>+ecuConfiguration 1</code> eine <code>EcucValueCollection</code>.\n</li><li><code>BswModuleTiming</code>: referenziert per gerichteter Assoziation <code>+behavior 1</code> ein <code>BswInternalBehavior</code> (erbt von <code>InternalBehavior</code>).\n</li><li><code>BswCompositionTiming</code>: referenziert per gerichteter Assoziation <code>+implementation 1..*</code> ein <code>BswImplementation</code> (erbt von <code>Implementation</code>). <code>BswImplementation</code> verweist wiederum per gerichteter Assoziation <code>+behavior 1</code> auf <code>BswInternalBehavior</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Sequenzabläufe oder Zustandsübergänge. Es definiert die statische Metamodellstruktur zur Erfassung von Timing-Garantien, -Anforderungen und -Beschreibungen entlang der AUTOSAR-Entwicklungsartefakte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>TimingExtension</code> strukturiert Timing-Beschreibungen und -Bedingungen, die über <code>«atpVariation,atpSplitable»</code> aufteilbar und variabilitätsfähig sind (<code>vh.latestBindingTime = postBuild</code>). Neben Komponenten-, System- und Modul-Timings existiert <code>BswCompositionTiming</code>, das BSW-Kompositionen über deren Implementierungen (<code>BswImplementation</code>) und das zugehörige BSW-Verhalten (<code>BswInternalBehavior</code>) mit Timing-Anforderungen und -Garantien verknüpft.</p>"}, {"id": "FIG-8b35c91bb28c7163", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des Metamodells für AUTOSAR Timing Extensions (<code>AUTOSAR_TPS_TimingExtensions</code>). Es stellt die Kernstruktur der Timing-Erweiterungen mit der abstrakten Basisklasse <code>TimingExtension</code>, deren Aggregationen von Beschreibungen und Bedingungen sowie deren Spezialisierungen für unterschiedliche architektonische Abstraktionsebenen und Sichten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Basisklasse ist <code>TimingExtension</code> (erbt von <code>PackageableElement</code> / <code>ARElement</code>). Sie aggregiert per Komposition mit <code>«atpVariation,atpSplitable»</code> und Kardinalität <code>0..*</code>:</p>\n<ul class=\"fig-list\"><li><code>+timingDescription</code>: verweist auf <code>TimingDescription</code> (erbt von <code>MultilanguageReferrable</code> / <code>Identifiable</code>).\n</li><li><code>+timingRequirement</code>: verweist auf <code>TimingConstraint</code> (erbt von <code>MultilanguageReferrable</code> / <code>Traceable</code>).\n</li><li><code>+timingGuarantee</code>: verweist auf <code>TimingConstraint</code>.\n</li></ul>\n<p class=\"fig-p\"><code>Identifiable</code> definiert die Attribute <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>.</p>\n<p class=\"fig-p\">Von <code>TimingExtension</code> leiten sich spezialisierte Timing-Klassen ab:</p>\n<ul class=\"fig-list\"><li><code>VfbTiming</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>): referenziert per gerichteter Assoziation <code>+component 1</code> ein <code>SwComponentType</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>).\n</li><li><code>SwcTiming</code>: referenziert per gerichteter Assoziation <code>+behavior 0..1</code> ein <code>SwcInternalBehavior</code> (erbt von <code>InternalBehavior</code>).\n</li><li><code>SystemTiming</code>: referenziert per gerichteter Assoziation <code>+system 1</code> ein <code>System</code> (erbt von <code>AtpStructureElement</code>).\n</li><li><code>EcuTiming</code>: referenziert per gerichteter Assoziation <code>+ecuConfiguration 1</code> eine <code>EcucValueCollection</code>.\n</li><li><code>BswModuleTiming</code>: referenziert per gerichteter Assoziation <code>+behavior 1</code> ein <code>BswInternalBehavior</code> (erbt von <code>InternalBehavior</code>).\n</li><li><code>BswCompositionTiming</code>: referenziert per gerichteter Assoziation <code>+implementation 1..*</code> ein <code>BswImplementation</code> (erbt von <code>Implementation</code>). <code>BswImplementation</code> verweist wiederum per gerichteter Assoziation <code>+behavior 1</code> auf <code>BswInternalBehavior</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Sequenzabläufe oder Zustandsübergänge. Es definiert die statische Metamodellstruktur zur Erfassung von Timing-Garantien, -Anforderungen und -Beschreibungen entlang der AUTOSAR-Entwicklungsartefakte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>TimingExtension</code> strukturiert Timing-Beschreibungen und -Bedingungen, die über <code>«atpVariation,atpSplitable»</code> aufteilbar und variabilitätsfähig sind (<code>vh.latestBindingTime = postBuild</code>). Neben Komponenten-, System- und Modul-Timings existiert <code>BswCompositionTiming</code>, das BSW-Kompositionen über deren Implementierungen (<code>BswImplementation</code>) und das zugehörige BSW-Verhalten (<code>BswInternalBehavior</code>) mit Timing-Anforderungen und -Garantien verknüpft.</p>"}, {"id": "FIG-572f0c6198ada76c", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des Metamodells für AUTOSAR Timing Extensions (<code>AUTOSAR_TPS_TimingExtensions</code>). Es stellt die Kernstruktur der Timing-Erweiterungen mit der abstrakten Basisklasse <code>TimingExtension</code>, deren Aggregationen von Beschreibungen und Bedingungen sowie deren Spezialisierungen für unterschiedliche architektonische Abstraktionsebenen und Sichten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Basisklasse ist <code>TimingExtension</code> (erbt von <code>PackageableElement</code> / <code>ARElement</code>). Sie aggregiert per Komposition mit <code>«atpVariation,atpSplitable»</code> und Kardinalität <code>0..*</code>:</p>\n<ul class=\"fig-list\"><li><code>+timingDescription</code>: verweist auf <code>TimingDescription</code> (erbt von <code>MultilanguageReferrable</code> / <code>Identifiable</code>).\n</li><li><code>+timingRequirement</code>: verweist auf <code>TimingConstraint</code> (erbt von <code>MultilanguageReferrable</code> / <code>Traceable</code>).\n</li><li><code>+timingGuarantee</code>: verweist auf <code>TimingConstraint</code>.\n</li></ul>\n<p class=\"fig-p\"><code>Identifiable</code> definiert die Attribute <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>.</p>\n<p class=\"fig-p\">Von <code>TimingExtension</code> leiten sich spezialisierte Timing-Klassen ab:</p>\n<ul class=\"fig-list\"><li><code>VfbTiming</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>): referenziert per gerichteter Assoziation <code>+component 1</code> ein <code>SwComponentType</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>).\n</li><li><code>SwcTiming</code>: referenziert per gerichteter Assoziation <code>+behavior 0..1</code> ein <code>SwcInternalBehavior</code> (erbt von <code>InternalBehavior</code>).\n</li><li><code>SystemTiming</code>: referenziert per gerichteter Assoziation <code>+system 1</code> ein <code>System</code> (erbt von <code>AtpStructureElement</code>).\n</li><li><code>EcuTiming</code>: referenziert per gerichteter Assoziation <code>+ecuConfiguration 1</code> eine <code>EcucValueCollection</code>.\n</li><li><code>BswModuleTiming</code>: referenziert per gerichteter Assoziation <code>+behavior 1</code> ein <code>BswInternalBehavior</code> (erbt von <code>InternalBehavior</code>).\n</li><li><code>BswCompositionTiming</code>: referenziert per gerichteter Assoziation <code>+implementation 1..*</code> ein <code>BswImplementation</code> (erbt von <code>Implementation</code>). <code>BswImplementation</code> verweist wiederum per gerichteter Assoziation <code>+behavior 1</code> auf <code>BswInternalBehavior</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Sequenzabläufe oder Zustandsübergänge. Es definiert die statische Metamodellstruktur zur Erfassung von Timing-Garantien, -Anforderungen und -Beschreibungen entlang der AUTOSAR-Entwicklungsartefakte.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>TimingExtension</code> strukturiert Timing-Beschreibungen und -Bedingungen, die über <code>«atpVariation,atpSplitable»</code> aufteilbar und variabilitätsfähig sind (<code>vh.latestBindingTime = postBuild</code>). Neben Komponenten-, System- und Modul-Timings existiert <code>BswCompositionTiming</code>, das BSW-Kompositionen über deren Implementierungen (<code>BswImplementation</code>) und das zugehörige BSW-Verhalten (<code>BswInternalBehavior</code>) mit Timing-Anforderungen und -Garantien verknüpft.</p>"}], "trans": [{"from": "FIG-9dd5d01a40b876de", "to": "FIG-f1496cd250b353db", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Kompositionen von <code>TimingExtension</code> zu <code>TimingDescription</code> (<code>+timingDescription</code>), <code>TimingConstraint</code> (<code>+timingRequirement</code>) und <code>TimingConstraint</code> (<code>+timingGuarantee</code>) erhalten zusätzlich das Stereotyp <code>«atpSplitable»</code> (vormals nur <code>«atpVariation»</code>).\n</li><li>Die Assoziation <code>+component 0..1</code> von <code>SwcTiming</code> auf <code>SwComponentType</code> samt zugehöriger Annotation <code>Association Tags: atp.Status = obsolete</code> wurde entfernt.\n</li><li>Die Bindungszeit-Annotation (<code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code>) ist im Notizfeld nicht mehr an das Attribut <code>uuid</code> gekoppelt, sondern bezieht sich nur noch auf die Kompositionen.\n</li></ul>"}, {"from": "FIG-f1496cd250b353db", "to": "FIG-4eaecf515185f41a", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4eaecf515185f41a", "to": "FIG-6bf3f37b0bd56be0", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neue Spezialisierung <code>BswCompositionTiming</code> erbt von <code>TimingExtension</code>.\n</li><li>Neue Assoziation von <code>BswCompositionTiming</code> zu <code>BswImplementation</code> mit Rollenname <code>+implementation</code> und Multiplizität <code>1..*</code>.\n</li><li>Neue gerichtete Assoziation von <code>BswImplementation</code> zu <code>BswInternalBehavior</code> mit Rollenname <code>+behavior</code> und Multiplizität <code>1</code>.\n</li><li>Die Klasse <code>BswModuleTiming</code> wurde im Layout nach unten verschoben, bleibt jedoch Spezialisierung von <code>TimingExtension</code> mit Assoziation <code>+behavior 1</code> zu <code>BswInternalBehavior</code>.\n</li></ul>"}, {"from": "FIG-6bf3f37b0bd56be0", "to": "FIG-8b35c91bb28c7163", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Die Beschriftungen der Assoziationsenden <code>+system 1</code> (von <code>SystemTiming</code> zu <code>System</code>), <code>+ecuConfiguration 1</code> (von <code>EcuTiming</code> zu <code>EcucValueCollection</code>) und <code>+behavior 0..1</code> (von <code>SwcTiming</code> zu <code>SwcInternalBehavior</code>) wurden entflochten und direkt an den jeweiligen Verbindungslinien platziert.\n</li></ul>"}, {"from": "FIG-8b35c91bb28c7163", "to": "FIG-572f0c6198ada76c", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
